#!/usr/bin/env python3
"""Build the dependency-free GitHub Pages product site."""
from pathlib import Path
from html import escape
import datetime
import json

ROOT=Path(__file__).resolve().parent.parent
OUT=ROOT/'docs'
BASE='https://senwong.github.io/gitviz-mygo/'
PREFIX='/gitviz-mygo/'
REPO='https://github.com/senwong/gitviz-mygo'
DOWNLOAD=REPO+'/releases/latest/download/Gitviz-macOS-universal.zip'
VERSION=json.loads((ROOT/'mygo.json').read_text())['version']

def link(path): return PREFIX+path

def screenshot(name,alt,priority=False):
    loading='fetchpriority="high"' if priority else 'loading="lazy"'
    return f'''<figure class="app-frame"><div class="window-bar"><span class="window-dots" aria-hidden="true"><i></i><i></i><i></i></span><span>gitviz-demo — Gitviz</span><span class="window-label">ACTUAL APP</span></div><a href="{link('assets/'+name+'.png')}" aria-label="Open full-size screenshot: {escape(alt)}"><img src="{link('assets/'+name+'.png')}" width="1440" height="960" alt="{escape(alt)}" {loading} decoding="async"></a><figcaption>Actual Gitviz interface · synthetic demo repository</figcaption></figure>'''

def buttons():
    return f'<div class="actions"><a class="button primary" href="{DOWNLOAD}">Download for macOS <span aria-hidden="true">↓</span></a><a class="button secondary" href="{REPO}">View on GitHub <span aria-hidden="true">↗</span></a></div><p class="requirements">v{VERSION} · macOS 13+ · Apple Silicon &amp; Intel</p>'

features=[
 ('01','History, connected.','Follow colored branch lanes and merge paths. See local branches, remote branches and tags together in a readable Git graph.'),
 ('02','The details stay with you.','Expand a commit inside the graph to read its message, parents and changed files. Open a file for a larger diff, then return with ⌘W.'),
 ('03','Every kind of change.','Find text in code diffs and copy across lines. For supported images, compare the versions stored in Git side by side.'),
 ('04','All your repositories.','Switch projects with ⌘P, search by repository name, or open the repositories in a VS Code .code-workspace file.'),
 ('05','Remote status, in view.','Check for remote branch and tag changes, inspect ahead/behind counts, and optionally Fetch on repository switches. Fetch does not pull or merge.'),
 ('06','A native place to work.','A standalone Go desktop application built with MyGo, with light and dark themes, visible shortcuts and last-repository restore.'),
]
faq=[
 ('What is Gitviz?','Gitviz is a native Git graph viewer and desktop Git client for macOS. It helps you explore commit history, branches and tags, inspect changes, and work across repositories.'),
 ('Is it a VS Code extension?','No. Gitviz is a standalone desktop application. Its workflow is inspired by VS Code Git Graph, but it is a separate project with its own implementation.'),
 ('Does switching repositories pull or change my local branch?','No. With automatic Fetch enabled, switching repositories refreshes remote refs and tags. It does not pull, merge or check out a different branch. Those are separate actions.'),
 ('Can I compare images?','Yes. Gitviz reads supported raster images from the selected Git revisions and shows before/after previews. Supported formats include PNG, JPEG, GIF (first frame), WebP, BMP and TIFF. A text-diff view remains available; preview limits apply to large images.'),
 ('Does it support Apple Silicon and Intel Macs?','Yes. The universal macOS download contains both arm64 and x86_64 binaries. It requires macOS 13 or later and an installed Git executable.'),
 ('Why does macOS ask me to allow the app?','The current release is ad-hoc signed and is not notarized by Apple. After trying to open it, you may need to allow it in System Settings → Privacy & Security → Open Anyway. See the installation guide for details.'),
 ('Does Gitviz need a GitHub account?','A GitHub account is not required for local Git repositories. Remote operations use your installed Git and its existing authentication configuration, whether your remotes are on GitHub or another Git server.'),
 ('Can I use it on Windows or Linux?','This project currently distributes and verifies the macOS application. Windows and Linux releases are not currently provided.'),
]

def faq_html(items):
    return '<div class="faq-list">'+''.join(f'<article><h3>{escape(q)}</h3><p>{escape(a)}</p></article>' for q,a in items)+'</div>'

def page(path,title,description,body,kind='article',lang='en'):
    url=BASE+path
    home=path==''
    schema={'@context':'https://schema.org','@graph':[
      {'@type':'WebSite','@id':BASE+'#website','name':'Gitviz','url':BASE,'inLanguage':['en','zh-CN']},
      {'@type':'WebPage','@id':url+'#page','url':url,'name':title,'description':description,'inLanguage':lang,'isPartOf':{'@id':BASE+'#website'},'about':{'@id':BASE+'#app'}},
    ]}
    if home:
        schema['@graph'].append({'@type':'SoftwareApplication','@id':BASE+'#app','name':'Gitviz','alternateName':'Gitviz MyGo','url':BASE,'description':description,'applicationCategory':'DeveloperApplication','operatingSystem':'macOS 13 or later','softwareVersion':VERSION,'downloadUrl':DOWNLOAD,'screenshot':BASE+'assets/gitviz-graph.png','image':BASE+'assets/social.png','offers':{'@type':'Offer','price':'0','priceCurrency':'USD'},'author':{'@type':'Person','name':'Shaosen Wang','url':'https://github.com/senwong'},'sameAs':[REPO]})
    alternates=''
    if path in ('','zh/'):
        alternates=f'<link rel="alternate" hreflang="en" href="{BASE}"><link rel="alternate" hreflang="zh-CN" href="{BASE}zh/"><link rel="alternate" hreflang="x-default" href="{BASE}">'
    links=''.join(f'<a href="{link(p)}"'+(' aria-current="page"' if path==p else '')+f'>{label}</a>' for p,label in [('features/','Features'),('install/','Install'),('faq/','FAQ')])
    html=f'''<!doctype html>
<html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{escape(title)}</title><meta name="description" content="{escape(description)}"><meta name="robots" content="index,follow,max-image-preview:large"><meta name="theme-color" content="#0e121a"><link rel="canonical" href="{url}">{alternates}<link rel="icon" type="image/svg+xml" href="{link('assets/icon.svg')}"><link rel="stylesheet" href="{link('style.css')}"><meta property="og:type" content="website"><meta property="og:site_name" content="Gitviz"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(description)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{BASE}assets/social.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="Gitviz — Native Git Graph Viewer for macOS"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{escape(title)}"><meta name="twitter:description" content="{escape(description)}"><meta name="twitter:image" content="{BASE}assets/social.png"><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script></head>
<body><a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="nav-shell"><a class="brand" href="{PREFIX}" aria-label="Gitviz home"><img src="{link('assets/icon.svg')}" width="40" height="40" alt=""><span>Gitviz</span></a><nav aria-label="Main navigation">{links}<a class="nav-source" href="{REPO}">GitHub <span aria-hidden="true">↗</span></a><a class="language" href="{link('' if lang=='zh-CN' else 'zh/')}" lang="{'en' if lang=='zh-CN' else 'zh-CN'}">{'EN' if lang=='zh-CN' else '中文'}</a></nav></div></header><main id="main" class="{kind}">{body}</main><footer><div class="footer-top"><a class="brand" href="{PREFIX}"><img src="{link('assets/icon.svg')}" width="32" height="32" alt=""><span>Gitviz</span></a><p>A clearer view of your Git history.</p></div><div class="footer-links"><a href="{link('features/')}">Features</a><a href="{link('comparison/')}">Git Graph comparison</a><a href="{link('install/')}">Installation</a><a href="{REPO}/releases">Releases</a><a href="{REPO}/issues">Report an issue</a><a href="{link('zh/')}" lang="zh-CN">中文说明</a></div><div class="footer-bottom"><span>Built with Go &amp; MyGo. Made for macOS.</span><span>By <a href="https://github.com/senwong">senwong</a></span></div></footer></body></html>'''
    target=OUT/path/'index.html'
    target.parent.mkdir(parents=True,exist_ok=True)
    target.write_text(html)

home=f'''<section class="hero shell"><p class="eyebrow"><span class="status-dot"></span> GITVIZ FOR MACOS</p><h1>A clearer view<br><span>of your Git history.</span></h1><p class="hero-copy">A native Git graph viewer for macOS. Follow branches, inspect commits, and compare changes across your repositories in a focused desktop app.</p>{buttons()}<p class="quiet-link">First time here? <a href="{link('install/')}">Read the installation guide <span aria-hidden="true">↗</span></a></p></section><div class="shell hero-shot">{screenshot('gitviz-graph','Gitviz commit graph with colored branch lanes, merge paths, branch labels and tags',True)}</div><section class="shell feature-section"><div class="section-heading"><p class="eyebrow">THE BIG PICTURE. THE SMALL DETAILS.</p><h2>Follow the story.<br><span>See what changed.</span></h2><p>Your branches, commits and files, connected in one calm workspace.</p></div><div class="feature-grid">{''.join(f'<article class="feature-card"><span class="feature-number">{n}</span><h3>{heading}</h3><p>{copy}</p></article>' for n,heading,copy in features)}</div></section><section class="shell detail-section"><div class="section-heading"><p class="eyebrow">FROM HISTORY TO THE DIFF</p><h2>One commit.<br><span>All the context.</span></h2><p>Read the message and changed files inline. Open a file when you want room to look closer.</p></div>{screenshot('gitviz-details','Gitviz inline commit details with parent commits and a changed-file tree')}<a class="text-link" href="{link('features/')}">Explore the features <span aria-hidden="true">→</span></a></section><section class="shell faq-section"><div class="section-heading"><p class="eyebrow">A FEW THINGS TO KNOW</p><h2>Before you open it.</h2></div>{faq_html(faq[:3])}<a class="text-link" href="{link('faq/')}">More questions, answered <span aria-hidden="true">→</span></a></section><section class="shell final-cta"><p class="eyebrow">A LITTLE LESS FRICTION.</p><h2>Meet your next<br>Git workspace.</h2>{buttons()}</section>'''
page('','Gitviz — Native Git Graph Viewer for macOS','Explore Git history, branches and tags in a native macOS Git client. Inspect commits, compare code and images, and switch repositories. Download Gitviz for Apple Silicon and Intel.',home,'home')

features_body=f'''<div class="shell article-shell"><p class="eyebrow">THE GITVIZ WORKSPACE</p><h1>A Git graph.<br><span>With the details.</span></h1><p class="lede">Explore repository history, then move directly into the changes that matter. Gitviz keeps graph navigation, commit details and file diffs close together.</p><div class="feature-grid">{''.join(f'<section class="feature-card"><span class="feature-number">{n}</span><h2>{heading}</h2><p>{copy}</p></section>' for n,heading,copy in features)}</div><section class="article-section"><h2>Read a commit in context</h2><p>Click a commit to expand its message, author, parents and changed files inside the graph. Click it again to collapse. Selecting a commit does not intentionally scroll it to the top.</p>{screenshot('gitviz-details','Commit metadata, message and changed files expanded inside the native Gitviz graph')}</section><section class="article-section"><h2>Give the diff some room</h2><p>Click a file to open a larger diff. Use ⌘F to find text, ⌘G to move between matches, and drag across lines to copy code with its spaces and line breaks. Use ⌘W or Back to Git Graph to return.</p>{screenshot('gitviz-diff','Gitviz full-size code diff with file navigation and highlighted additions and deletions')}</section><section class="article-section"><h2>Compare image versions</h2><p>Supported PNG, JPEG, GIF, WebP, BMP and TIFF files open in a before/after preview. Gitviz reads committed images from Git blobs, not from the current working copy. Added and deleted images show the available side. GIF previews show the first frame.</p><p>To keep memory use bounded, previews are limited to 32 MiB and 40 megapixels per image. Unsupported or damaged data, including unavailable Git LFS content, displays a fallback message. The raw text diff remains available.</p></section><section class="article-section"><h2>Understand remote freshness</h2><p>A local ahead/behind count compares cached refs. Gitviz can separately check configured remotes for branch and tag changes. The footer distinguishes unchecked, checking, current, fetch-needed and failed states, and records the check time. A successful check becomes stale after five minutes; it is not a continuous guarantee.</p><p>Automatic Fetch can run when switching repositories. After a successful automatic Fetch and graph reload, the graph scrolls to the top. Fetch does not pull or merge remote commits into the checked-out branch.</p></section><section class="article-section"><h2>Work with branches, commits and tags</h2><p>Context menus provide operations such as checkout, branch and tag creation, merge, rebase, cherry-pick and revert. Available actions depend on the selected reference and repository state. Gitviz uses your installed Git and existing credentials for remote operations.</p></section><section class="article-section"><h2>Keyboard shortcuts</h2><dl class="shortcut-list">{''.join(f'<div><dt><kbd>{key}</kbd></dt><dd>{value}</dd></div>' for key,value in [('⌘P','Choose a repository'),('⌘⇧P','Open the command palette'),('⌘B','Choose a branch filter'),('⌘F','Find in the graph or current text diff'),('⌘G / ⌘⇧G','Next / previous match'),('⌘R','Refresh the graph'),('⌘,','Open settings'),('⌘W','Return from diff; otherwise close the window'),('⌘Q','Quit the app')])}</dl></section><div class="inline-cta"><h2>Ready to look closer?</h2>{buttons()}</div></div>'''
page('features/','Gitviz Features — Git Graph, Commit Details & File Diffs for macOS','See Gitviz features: colored Git branch graphs, inline commit details, code and image diffs, repository switching, remote status and keyboard shortcuts.',features_body)

install_body=f'''<div class="shell article-shell narrow"><p class="eyebrow">START HERE</p><h1>A few steps.<br><span>A clearer history.</span></h1><p class="lede">Install Gitviz on macOS, open a repository, and explore its Git graph.</p><section class="article-section"><h2>Requirements</h2><ul><li>macOS 13 or later.</li><li>An Apple Silicon or Intel Mac. The download is a universal app.</li><li>Git installed and available on your system.</li></ul><p>If Git is not installed, install Apple’s Command Line Tools:</p><pre><code>xcode-select --install</code></pre></section><section class="article-section"><h2>1. Download and install</h2><p><a href="{DOWNLOAD}">Download Gitviz for macOS</a>, open the ZIP, and drag <code>gitviz.app</code> to your Applications folder.</p><p>The current version is {VERSION}. <a href="{REPO}/releases">Release notes and previous versions</a> are available on GitHub.</p></section><section class="article-section callout"><h2>2. Allow the app on first launch</h2><p>The current download is ad-hoc signed. It is <strong>not notarized by Apple</strong>, so macOS may block the first launch.</p><ol><li>Try opening Gitviz from Applications.</li><li>Open <strong>System Settings → Privacy &amp; Security</strong>.</li><li>Find the blocked-app message and choose <strong>Open Anyway</strong>, if available.</li><li>Confirm the system prompt, then open Gitviz again.</li></ol><p>Only proceed with a download you trust. For current system instructions, see <a href="https://support.apple.com/en-us/102445">Apple’s guide to opening apps safely</a>.</p></section><section class="article-section"><h2>3. Open a repository or workspace</h2><p>Use Open Repository in the app, or open a VS Code <code>.code-workspace</code> file to load its repositories. Press ⌘P to find and switch repositories by name. On the next launch, Gitviz restores the last opened repository.</p><p>You can also launch it from Terminal:</p><pre><code>open -a /Applications/gitviz.app --args /path/to/repository</code></pre></section><section class="article-section"><h2>Verify the download</h2><p>Download <a href="{REPO}/releases/latest/download/SHA256SUMS.txt">SHA256SUMS.txt</a> from the same release as the ZIP. In the folder containing both files, run:</p><pre><code>shasum -a 256 -c SHA256SUMS.txt</code></pre><p>The result should be <code>Gitviz-macOS-universal.zip: OK</code>. The checksum checks that the file matches the published asset; it is not a substitute for Apple notarization.</p></section><section class="article-section"><h2>Build from source</h2><p>Use macOS, Git and Go 1.27.3 or later. The MyGo dependency is pinned in <code>go.mod</code>.</p><pre><code>git clone {REPO}.git
cd gitviz-mygo
./script/build
./build/gitviz-mygo /path/to/repository</code></pre><p>Run <code>./script/package</code> for an app for the current architecture, or <code>./script/release</code> for the universal macOS ZIP.</p></section><section class="article-section"><h2>Remote authentication and settings</h2><p>Gitviz uses your installed Git executable and existing authentication. If a remote operation fails, verify that the same Git command works in Terminal. App settings are stored in <code>~/.config/gitviz-mygo/</code>.</p><p>If you need help, <a href="{REPO}/issues">open an issue</a> with your macOS version, Gitviz version and the error message. Do not include credentials or private repository data.</p></section></div>'''
page('install/','Install Gitviz on macOS — Apple Silicon & Intel Download','Download and install Gitviz for macOS 13+. Includes Apple Silicon and Intel support, first-launch instructions, SHA-256 verification and source build commands.',install_body)

comparison_body=f'''<div class="shell article-shell narrow"><p class="eyebrow">A FAMILIAR WORKFLOW. A SEPARATE APP.</p><h1>Gitviz and<br><span>VS Code Git Graph.</span></h1><p class="lede">Gitviz is for people who want to explore a Git graph in a standalone macOS application. It takes inspiration from the Git Graph workflow while providing its own native desktop interface.</p><section class="article-section"><h2>Choose the workspace that fits you</h2><p><a href="https://github.com/mhutchie/vscode-git-graph">VS Code Git Graph</a> is an extension used inside Visual Studio Code. Gitviz is an independent desktop app; it does not require VS Code to be open.</p><p>If your Git workflow is already centered on your editor, the extension may be the right fit. If you want a separate window for repository history and diffs across projects, try Gitviz.</p></section><section class="article-section"><h2>What will feel familiar?</h2><ul><li>Colored branch lanes and commit nodes.</li><li>Branch and tag labels alongside commit messages.</li><li>Commit details with parent links and changed files.</li><li>Context menus for Git operations.</li><li>Finding commits by message, author, SHA or reference.</li></ul></section><section class="article-section"><h2>What does Gitviz offer as a desktop app?</h2><ul><li>Its own native macOS window and keyboard shortcuts.</li><li>A repository picker and support for VS Code workspace files.</li><li>Full-size text diffs with search and multiline copy.</li><li>Before/after previews for supported images.</li><li>Remote branch/tag freshness checks and optional Fetch on repository changes.</li></ul></section><section class="article-section callout"><h2>Independent projects</h2><p>Gitviz is not affiliated with or endorsed by the maintainers of VS Code Git Graph or Microsoft. It does not claim complete feature parity with the extension. Refer to each project’s documentation for its current behavior.</p></section><div class="inline-cta"><h2>Try a dedicated Git workspace.</h2>{buttons()}</div></div>'''
page('comparison/','Gitviz vs VS Code Git Graph — A Standalone macOS Git Viewer','Compare workflows: Gitviz is an independent native macOS Git graph application, while Git Graph runs inside VS Code. Find the right workspace for your Git history.',comparison_body)

page('faq/','Gitviz FAQ — macOS Support, Git Fetch, Image Diffs & Installation','Answers about Gitviz: macOS requirements, Apple Silicon and Intel support, Git authentication, automatic Fetch, image previews and first-launch installation.',f'<div class="shell article-shell narrow"><p class="eyebrow">GOOD QUESTIONS</p><h1>A little more<br><span>about Gitviz.</span></h1><p class="lede">The practical details before you start exploring.</p>{faq_html(faq)}<p class="article-section">Still have a question? <a href="{REPO}/issues">Open an issue on GitHub</a>.</p></div>')

zh=f'''<div class="shell article-shell"><p class="eyebrow">GITVIZ · 原生 MACOS 应用</p><h1>看清每次提交，<br><span>读懂分支之间的关系。</span></h1><p class="lede">Gitviz 是一个独立的 macOS Git 图形客户端。浏览提交历史、分支和标签，行内展开提交详情，查看代码与图片差异，并快速切换仓库。</p><div class="actions"><a class="button primary" href="{DOWNLOAD}">下载 macOS 版 <span aria-hidden="true">↓</span></a><a class="button secondary" href="{REPO}">在 GitHub 查看源码 ↗</a></div><p class="requirements">v{VERSION} · macOS 13 及以上 · Apple Silicon 与 Intel 通用版本</p>{screenshot('gitviz-graph','Gitviz 原生界面展示演示仓库的提交图、分支和标签',True)}<section class="article-section"><h2>主要功能</h2><ul><li>彩色提交关系图，同时展示本地分支、远程分支与 tag。</li><li>行内查看提交信息、父提交和文件树；点击文件打开大幅 diff。</li><li>在文本 diff 中搜索、多行选中和复制，预览图片的修改前后版本。</li><li>使用 ⌘P 按名称切换仓库，支持 VS Code .code-workspace 工作区。</li><li>检查远程分支和 tag 是否更新，显示当前分支的 ahead/behind 状态。</li><li>可选切换仓库自动 Fetch，支持明暗主题与上次仓库恢复。</li></ul></section><section class="article-section"><h2>安装方式</h2><p>下载 ZIP、解压，然后将 <code>gitviz.app</code> 拖入 Applications。系统需要已安装 Git；没有 Git 时，可运行 <code>xcode-select --install</code> 安装 Apple 命令行工具。</p><p>当前版本使用本机临时签名，尚未经过 Apple 公证。首次启动可能需要在“系统设置 → 隐私与安全性”中选择“仍要打开”。<a href="{link('install/')}">完整安装与校验说明（英文）</a>。</p></section><section class="article-section"><h2>Fetch 不会自动 Pull</h2><p>自动 Fetch 更新远程引用与 tag，不会自动合并代码，也不会替你切换本地分支。本地分支是否落后仍会单独显示。</p></section><section class="article-section"><h2>项目与源码</h2><p>本仓库是使用 Go 和 MyGo 构建的实现，与 <a href="https://github.com/senwong/gitviz">Rust 版 Gitviz</a> 独立维护。Gitviz 不是 VS Code 扩展，也不声称与 VS Code Git Graph 完全功能一致。</p><p><a href="{REPO}/blob/main/README.zh-CN.md">中文构建说明</a> · <a href="{REPO}/releases">版本发布</a> · <a href="{REPO}/issues">反馈问题</a></p></section></div>'''
page('zh/','Gitviz — macOS 原生 Git 提交图与文件差异查看器','Gitviz 是 macOS 原生 Git 图形客户端，支持提交关系图、分支与标签、行内提交详情、代码和图片 diff、多仓库切换及远程更新检查。适用于 Apple Silicon 和 Intel Mac。',zh,lang='zh-CN')

page('404/','Page Not Found — Gitviz','This Gitviz page could not be found.',f'<div class="shell article-shell narrow"><p class="eyebrow">404</p><h1>Wrong branch.</h1><p class="lede">This page could not be found. Head back to the <a href="{PREFIX}">Gitviz home page</a> or read the <a href="{link("install/")}">installation guide</a>.</p></div>')
not_found=(OUT/'404/index.html').read_text().replace('content="index,follow,max-image-preview:large"','content="noindex,follow"')
(OUT/'404.html').write_text(not_found)
# The Pages site serves 404.html; a second indexed 404/ route is unnecessary.
(OUT/'404/index.html').unlink();(OUT/'404').rmdir()
(OUT/'.nojekyll').write_text('')
paths=['','features/','install/','comparison/','faq/','zh/']
(OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join(f'  <url><loc>{BASE+p}</loc></url>\n' for p in paths)+'</urlset>\n')
print('Built',len(paths),'pages and sitemap in',OUT)
